-- 1) Kratice iz pregleda
INSERT INTO public.training_codes (code, meaning, category, explanation, created_by)
SELECT v.code, v.meaning, v.category, v.explanation, (SELECT id FROM public.trainers WHERE email = 'uros.jedlovcnik@gmail.com' LIMIT 1)
FROM (VALUES
  ('CT', 'cela tehnika', 'izpeljava', 'Cela tehnika (celo plavanje).'),
  ('N', 'noge', 'izpeljava', 'Noge; N/V/CT = noge / vaje / cela tehnika po dolžinah ali po ponovitvah.'),
  ('BD', 'brez dihanja', 'drugo', 'Brez dihanja (KBD = kravl brez dihanja).'),
  ('MBK', 'mešano brez kravla', 'tehnika', NULL),
  ('MBD', 'mešano brez delfina', 'tehnika', NULL),
  ('MBP', 'mešano brez prsnega', 'tehnika', NULL),
  ('BP', 'brez prsnega', 'drugo', 'Brez prsnega (MM BP = mešano menjajoče brez prsnega).'),
  ('KVL', 'kravl z valčkom in lopatkami', 'tehnika', 'Kravl z valčkom in lopatkami (K + VL).'),
  ('ZD', 'z desko', 'rekvizit', 'Z desko (DE).'),
  ('STOP', 'stopnjevano', 'stopnjevanje', NULL),
  ('KZ', 'kravl, vaja zavesljaji (dihanje na stran ali kontra)', 'vaja', 'Kravl vaja zavesljaji; dve različici: dihanje na stran zavesljaja in dihanje kontra (KZ DK).'),
  ('PPV', 'prsno pod vodo', 'vaja', 'Prsno pod vodo.'),
  ('POPAJ', 'vaja sculling', 'vaja', 'Ena od vaj sculling.'),
  ('DOLGO', 'počasi (pri KV dolg zavesljaj)', 'intenzivnost', 'NA DOLGO = počasi; pri KV pomeni dolg zavesljaj.'),
  ('BOK', 'noge na boku', 'vaja', 'Noge na boku (KN BOK, DN BOK).'),
  ('OBRAT', 'obrat (MAX OBRAT = šprint v obrat in iz njega)', 'drugo', 'MAX OBRAT = šprint v obrat in iz njega, čim hitreje.'),
  ('DIH', 'dihanje na N zavesljajev (DIH 3-5-7)', 'drugo', 'Na koliko zavesljajev vdihneš; DIH 3-5-7 pri 75 m = vsakih 25 m drugače; DIH NA 1 = ob vsakem zavesljaju.'),
  ('ZAMIKOM', 'mešano z zamikom: vsakih 100 m začneš z naslednjo tehniko', 'drugo', 'Mešano z zamikom: pravilni red D, H, P, K; vsakih 100 m začneš z naslednjo tehniko.'),
  ('ČMZ', 'čim manj zavesljajev', 'vaja', 'Čim manj zavesljajev na dolžino.'),
  ('NPV', 'noge pod vodo', 'vaja', 'Noge pod vodo.'),
  ('PD', 'prsno drsenje', 'vaja', 'Prsno drsenje (vaja).'),
  ('HITLER', 'HV: roka ven iz vode, pri 90° dotik prsnega koša', 'vaja', 'HV: roka gre ven iz vode, pri 90° se dotakneš prsnega koša, nato nadaljuješ.'),
  ('PREVAL', 'preval', 'vaja', 'Preval (npr. 8x25 PL + PREVAL).'),
  ('STIL', 'prosta izbira tehnike', 'drugo', 'Prosta izbira tehnike; plavalci izberejo sami.'),
  ('RRU', 'roka roka ujame (sklop vaj)', 'vaja', NULL),
  ('PESTI', 'RRU s stisnjeno pestjo', 'vaja', 'RRU s stisnjeno pestjo.'),
  ('PALEC', 'RRU: palec se dotakne stegna in pazduhe', 'vaja', 'RRU: s palcem se dotakneš stegna in pazduhe.'),
  ('ŠPRICANJE', 'RRU/vaterpolo: ob koncu potega izpljuskneš vodo', 'vaja', 'RRU ali vaterpolo: ob koncu potega izpljuskneš vodo ven.'),
  ('GERMANJA', 'pomožna tehnika (podvodni del hrbtnega potega)', 'vaja', 'Pomožna tehnika; za razplavanje ali s hrbtno nogami kot vaja za podvodni del hrbtnega potega.'),
  ('ORKA', 'delfin noge s podvodnim delom zavesljaja', 'vaja', 'Delfin noge, samo podvodni del zavesljaja, roke vrneš naprej.'),
  ('ROTACIJA', 'rotacija ramenskega obroča', 'vaja', 'Predvsem pri hrbtno nogah ali vajah za rotacijo ramenskega obroča.'),
  ('SIMULATOR', '50 m + natanko 10 s + 50 m, simuliran čas tekme', 'vaja', 'Vaja hitrosti: 50 m, natanko 10 s počitka, 50 m; vsota je simuliran čas na tekmi.'),
  ('PACMAN', 'z lopatkami, lopatka na dnu', 'vaja', 'Z lopatkami: lopatko držiš na dnu, sili te v pravilen poteg.'),
  ('ZADUŠNICA', 'zadnjih 7 m pod vodo z delfin nogami', 'vaja', 'Zadnjih 7 m pod vodo: potopiš se in v cilj prideš z delfin nogami.'),
  ('ROTULJICA', 'metuljček, pomožna tehnika med delfinom in prsnim', 'vaja', 'Metuljček, pomožna tehnika med delfinom in prsnim.'),
  ('KRAJŠANJE', 'PV: trije vse krajši zavesljaji', 'vaja', 'PV: trije zaporedni zavesljaji, vsak krajši (dolg, srednji, kratek), nato spet dolg.'),
  ('RINEŠ', 'RRU: dlan pod vodo porineš naprej', 'vaja', 'RRU: dlan med vračanjem naprej pod vodo porineš naprej.'),
  ('SHARK', 'kravl vaja s komolcem nad ramo (SHARK 1/2/3)', 'vaja', NULL),
  ('NOGE', 'noge', 'izpeljava', NULL),
  ('VAJE', 'vaje', 'izpeljava', NULL),
  ('MAX', 'maksimalno', 'intenzivnost', NULL),
  ('SPRINT', 'šprint', 'intenzivnost', NULL),
  ('NORMALNO', 'normalno plavanje', 'drugo', NULL),
  ('3+1', '3 tempo, 1 hitro', 'stopnjevanje', 'Lahko v kateri koli tehniki.'),
  ('2+1', '2 tempo, 1 hitro', 'stopnjevanje', 'Lahko v kateri koli tehniki.'),
  ('4-3-2-1', 'razdelitev intenzivnosti: 4 POČ, 3 T, 2 HIT, 1 Max', 'stopnjevanje', 'Npr. 10x50 PL K 4-3-2-1 @55".'),
  ('L/D', '25 m leva roka, 25 m desna roka', 'vaja', 'Npr. 8x50 KV L/D.'),
  ('6-1', 'vaja hrbtno: na 6 udarcev nog zamenjaš roki', 'vaja', NULL),
  ('1-1-2', 'vaja delfin: 1 zavesljaj z levo, 1 z desno, 2 cela koordinacija', 'vaja', '2-2-2 je enaka vaja z enim zavesljajem več.'),
  ('ROKA UZ ZAVES', 'HV, kombinacija z 90°: hrbtno zavesljaji, druga roka je zunaj', 'vaja', NULL),
  ('MENJAMO POLOŽAJ', 'pri DN: hrbet, trebuh, en bok, drugi bok', 'vaja', NULL),
  ('ČIM DLJE POD VODO', 'plavanje pod vodo: prsno, kravl, delfin ali hrbtno noge', 'vaja', NULL),
  ('VISOK KOMOLEC', 'čim višje zarotiraš ramenski obroč, dvigneš ramo in komolec', 'vaja', 'Kot K CT ali KV RRU visok komolec.'),
  ('90°', 'noge hrbtno ali kravl z roko iz vode; ali hrbtno RRU, kjer roka čaka zunaj', 'vaja', NULL)
) AS v(code, meaning, category, explanation)
WHERE NOT EXISTS (SELECT 1 FROM public.training_codes x WHERE upper(x.code) = upper(v.code)
                    OR upper(v.code) = ANY (SELECT upper(a) FROM unnest(x.aliases) a))
ON CONFLICT ((lower(code))) DO NOTHING;

-- 2) Razlage obstoječih vaj
UPDATE public.training_codes SET explanation = 'Kravl noge, ena roka ob telesu, druga spredaj; dihaš na stran.' WHERE code = 'SUPERMAN';
UPDATE public.training_codes SET explanation = 'SHARK 1: komolec zadržiš visoko nad ramo 2–3 s, nato nadaljuješ. SHARK 2: ko pride komolec do rame, roko vrneš ob telo, nato cel zavesljaj. SHARK 3: roko vrneš ob telo in pod vodo naprej do izhodišča, nato cel zavesljaj.' WHERE code = 'SHARK';
UPDATE public.training_codes SET explanation = 'Kravl z glavo nad vodo.' WHERE code = 'VATERPOLO';
UPDATE public.training_codes SET explanation = 'Sklop vaj za občutek za vodo; plava se zelo počasi (npr. POPAJ).' WHERE code = 'SCULLING';
UPDATE public.training_codes SET explanation = 'RRU (zipper): s palcem vlečeš po robu telesa ves čas do rame.' WHERE code = 'ZADRGA';
UPDATE public.training_codes SET explanation = 'Roka roka ujame: sklop kravl vaj, kjer roka vedno počaka drugo (PESTI, PALEC, ZADRGA, ŠPRICANJE, RINEŠ).' WHERE code = 'RRU';
UPDATE public.training_codes SET explanation = 'Delfin vaje. DV 3-3 = 3x noge, 3x cela koordinacija; DV 2-2-1 je različica.' WHERE code = 'DV';

